647	            applyResponsePolicy({ request: policyRequest, response: selected.value }),
648	            { withoutBody: request.method === "HEAD" },
649	          );
650	        }
651	        // TanStack permits either a synchronous result or a Promise. tryPromise also
652	        // captures a synchronous throw from the framework callback.
653	        const result = yield* Effect.tryPromise({
654	          try: () => Promise.resolve(continueRequest()),
655	          catch: () => new HostAdapterError({ operation: "framework" }),
656	        });
657	        // Preserve the site's explicit 400/404/503 response status after Router
658	        // renders its native not-found or error component.
659	        const requestedStatus = yield* Effect.sync(getResponseStatus);
660	        const status = Match.value(requestedStatus).pipe(
661	          Match.when(200, () => result.response.status),
662	          Match.orElse((value) => value),
663	        );
664	        const appearanceHeader = yield* Effect.sync(() => request.headers.get("cookie") ?? "").pipe(
665	          Effect.flatMap(readAppearanceCookieHeader),
666	        );
667	        const savedAppearance = yield* readSavedAppearanceCookie(
668	          appearanceHeader,
669	          appearanceOptions,
670	        );
671	        const policy = responsePolicyHeaders({
672	          ...policyRequest,
673	          privateResponse:
674	            hasAppearanceCookie(appearanceHeader, appearanceOptions) &&
675	            Option.isNone(savedAppearance),
676	          varyCookie: true,
677	          status,
678	          headers: Headers.fromInput(result.response.headers),
679	          cookies: Cookies.empty,
680	        });
681	        // TanStack tracks the original response stream for SSR cleanup. Preserve its body
682	        // identity here; wrapping it in an Effect Stream would make TanStack close it early.
683	        return yield* Effect.try({
684	          try: () => {
685	            const headers = new globalThis.Headers(result.response.headers);
686	            Function.pipe(
687	              Record.toEntries(policy),
688	              Array.forEach(([name, value]) => {
689	                headers.set(name, value);
690	              }),
691	            );
692	            return {
693	              ...result,
694	              response: new Response(result.response.body, {
695	                status,
696	                statusText: result.response.statusText,
697	                headers,
698	              }),
699	            };
700	          },
701	          catch: () => new HostAdapterError({ operation: "framework" }),
702	        });
703	      }).pipe(observeWebsiteRequest(request)),
704	      signal: request.signal,
705	    }),
706	);
