import * as AtomRegistry from "effect/reactivity/AtomRegistry";
import type { LoaderContext } from "./loader-context";
import { AppearanceSettings } from "@common-practice/appearance/service";
import * as Layer from "effect/Layer";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";
import * as Atom from "effect/reactivity/Atom";
import * as FetchHttpClient from "effect/http/FetchHttpClient";
import { BrowserAnalytics, AnalyticsSettings } from "@common-practice/analytics/service";
import type { NavigationUse, PageView } from "@common-practice/analytics/schemas";
import { browserAnalyticsLayer } from "./analytics/browser.adapter.layer";
import { ContentApi } from "@common-practice/http/api";
import * as AtomHttpApi from "effect/reactivity/AtomHttpApi";
import * as HttpClient from "effect/http/HttpClient";
import * as HttpClientRequest from "effect/http/HttpClientRequest";
import * as HttpClientError from "effect/http/HttpClientError";
import * as Context from "effect/Context";
import { readPage, readCourseInput, readTrainingPageInput } from "./api/load.egress";
import { readCourses } from "./training/load.egress";
import type { PageInput } from "@common-practice/content/schemas";
import { WebsiteConfig } from "./api/page.egress";
import { ContentTools } from "@common-practice/mcp/tools";
import { ContentUnavailableError } from "@common-practice/content/errors";
import { TrainingUnavailableError } from "@common-practice/training/errors";
import { contentClientTimeout } from "@common-practice/content/service";
import { trainingClientTimeout } from "@common-practice/training/service";
import { requestPage, requestCourse } from "./api/requests";
import { rejectRouteLoad } from "./seo/load.failure";
import { WebsiteBrowserConfig } from "./api/config.ingress";
import { ApiConfigError } from "./api/config.errors";
import { WebsiteIdentity } from "./webmcp/identity.service";
import { ModelContextHostLive } from "./webmcp/model-context.adapter.layer";
import { registerWebMcpTools } from "./webmcp/registration.egress";
import { browserAppearanceLayer } from "@common-practice/appearance/live";
import { makeAppearanceModel } from "@common-practice/appearance/atoms";
import { appearanceOptions } from "./appearance/settings";
import { readAppearanceControlInput } from "./appearance/input.ingress";
import type { AppearanceControlInput } from "./appearance/input.ingress";

// Local state and the native HTTP service share one registry. React owns its lifetime. Mounting
// `webMcpAtom` registers the page tools with the browser's WebMCP host; unmounting closes the
// atom's Scope, which unregisters them. Nothing here reads a browser global when the module
// loads, so importing it during server rendering is safe and registers nothing.
export const browserConfigAtom = Atom.make(Option.none<typeof WebsiteBrowserConfig.Encoded>()).pipe(
  Atom.keepAlive,
);
export const websiteConfigAtom = Atom.make<typeof WebsiteConfig.Encoded>(
  WebsiteConfig.cases.WebsiteUnavailable.make({ appearance: "device" }),
).pipe(Atom.keepAlive);
const browserAppearanceLayerAtom = Atom.make(
  browserAppearanceLayer.pipe(Layer.provide(Layer.succeed(AppearanceSettings, appearanceOptions))),
);
// Test registries can supply the same closed service without creating a runtime.
export const browserAnalyticsLayerAtom = Atom.make(
  Option.none<Layer.Layer<BrowserAnalytics>>(),
).pipe(Atom.keepAlive);
export const browserRuntime = Atom.runtime((get) => get(browserAppearanceLayerAtom));
// Decode remote configuration once without acquiring either remote service.
// Local appearance and progress do not depend on this Atom.
const checkedBrowserConfigAtom = browserRuntime
  .atom((get) =>
    get(browserConfigAtom).pipe(
      Effect.fromOption,
      Effect.mapError(() => new ApiConfigError({ reason: "unavailable" })),
      Effect.flatMap(Schema.decodeEffect(WebsiteBrowserConfig)),
    ),
  )
  .pipe(Atom.keepAlive);

export const browserApiTransportAtom = Atom.make(
  FetchHttpClient.layer.pipe(
    Layer.provide(
      Layer.succeed(FetchHttpClient.RequestInit, { credentials: "omit", redirect: "error" }),
    ),
  ),
).pipe(Atom.keepAlive);

// Native service construction owns the protocol and client; pages and tools share it.
export class ApiClient extends AtomHttpApi.Service<ApiClient>()(
  "common-practice/BrowserApiClient",
  {
    api: ContentApi,
    runtime: browserRuntime.factory,
    httpClient: (get) =>
      Layer.effect(
        HttpClient.HttpClient,
        HttpClient.HttpClient.pipe(
          Effect.map((client) =>
            client.pipe(
              HttpClient.mapRequestEffect((request) =>
                get.result(checkedBrowserConfigAtom, { suspendOnWaiting: true }).pipe(
                  Effect.map((config) => HttpClientRequest.prependUrl(request, config.apiOrigin)),
                  Effect.mapError(
                    (cause) =>
                      new HttpClientError.HttpClientError({
                        reason: new HttpClientError.InvalidUrlError({ request, cause }),
                      }),
                  ),
                ),
              ),
            ),
          ),
        ),
      ).pipe(Layer.provide(get(browserApiTransportAtom))),
  },
) {}
// Native retention keeps the connection available between route loads. The Layer
// cache also shares this service with any native query atom using ApiClient.runtime.
const apiClientRuntime = ApiClient.runtime.pipe(Atom.keepAlive);
export const browserApiClient = Atom.getResult(checkedBrowserConfigAtom, {
  suspendOnWaiting: true,
}).pipe(
  Effect.andThen(Atom.getResult(apiClientRuntime, { suspendOnWaiting: true })),
  Effect.map(Context.get(ApiClient)),
);

const BrowserToolHandlers = ContentTools.toLayer(
  Effect.gen(function* () {
    const client = yield* ApiClient;
    return ContentTools.of({
      list_pages: () =>
        client.pages.listPages({}).pipe(
          Effect.timeout(contentClientTimeout),
          Effect.map((pages) => ({ pages })),
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
            SchemaError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
            TimeoutError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "list-pages" })),
          }),
        ),
      get_page: (input) =>
        requestPage({ client, input }).pipe(
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
            SchemaError: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
            TimeoutError: () => Effect.fail(new ContentUnavailableError({ operation: "get-page" })),
          }),
        ),
      list_courses: () =>
        client.courses.listCourses({}).pipe(
          Effect.timeout(trainingClientTimeout),
          Effect.map((courses) => ({ courses })),
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "list-courses" })),
            SchemaError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "list-courses" })),
            TimeoutError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "list-courses" })),
          }),
        ),
      get_course: (input) =>
        requestCourse({ client, input }).pipe(
          Effect.catchTags({
            HttpClientError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "get-course" })),
            SchemaError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "get-course" })),
            TimeoutError: () =>
              Effect.fail(new TrainingUnavailableError({ operation: "get-course" })),
          }),
        ),
    });
  }),
);
// Analytics consumers share one client until the root registry closes. WebMCP
// registration never reads this Atom, so it does not initialise the SDK.
const analyticsServicesAtom = browserRuntime
  .atom((get) => {
    const analyticsLayer = get(browserAnalyticsLayerAtom);
    return Layer.build(
      Layer.unwrap(
        get
          .result(checkedBrowserConfigAtom, { suspendOnWaiting: true })
          .pipe(
            Effect.map((config) =>
              Option.getOrElse(analyticsLayer, () =>
                browserAnalyticsLayer
                  .pipe(Layer.provide(Layer.succeed(AnalyticsSettings, config.analytics)))
                  .pipe(
                    Layer.provide(Layer.succeed(WebsiteIdentity, { origin: config.websiteOrigin })),
                  ),
              ),
            ),
          ),
      ),
    );
  })
  .pipe(Atom.keepAlive);
export const withBrowserAnalytics = <A, E>(program: Effect.Effect<A, E, BrowserAnalytics>) =>
  Atom.getResult(analyticsServicesAtom, { suspendOnWaiting: true }).pipe(
    Effect.flatMap((services) => program.pipe(Effect.provide(services))),
  );

export const appearanceAtoms = makeAppearanceModel(browserRuntime);
export const appearanceControlAtom = browserRuntime
  .fn(
    Effect.fn("Browser.chooseAppearanceFromControl")(function* (input: AppearanceControlInput) {
      // Retain the scheduler yield so Atom tracks a child before input failure.
      yield* Effect.yieldNow;
      yield* appearanceAtoms.change(yield* readAppearanceControlInput(input));
    }),
    { concurrent: true },
  )
  .pipe(Atom.keepAlive);
export const webMcpAtom = browserRuntime.atom((get) =>
  Layer.build(
    Layer.unwrap(
      get
        .result(checkedBrowserConfigAtom, { suspendOnWaiting: true })
        .pipe(
          Effect.flatMap((config) =>
            get
              .result(apiClientRuntime, { suspendOnWaiting: true })
              .pipe(
                Effect.map((services) =>
                  Layer.mergeAll(
                    ModelContextHostLive.pipe(
                      Layer.provide(
                        Layer.succeed(WebsiteIdentity, { origin: config.websiteOrigin }),
                      ),
                    ),
                    BrowserToolHandlers.pipe(Layer.provide(Layer.succeedContext(services))),
                  ),
                ),
              ),
          ),
        ),
    ),
  ).pipe(Effect.flatMap((services) => registerWebMcpTools.pipe(Effect.provide(services)))),
);
export const pageViewAtom = browserRuntime.fn(
  Effect.fn("Browser.recordPageView")((input: PageView) =>
    Effect.gen(function* () {
      const analytics = yield* BrowserAnalytics;
      yield* analytics.recordPageView(input);
    }).pipe(withBrowserAnalytics),
  ),
  { concurrent: true },
);
export const navigationAtom = browserRuntime.fn(
  Effect.fn("Browser.recordNavigation")((input: NavigationUse) =>
    Effect.gen(function* () {
      const analytics = yield* BrowserAnalytics;
      yield* analytics.recordNavigation(input);
    }).pipe(withBrowserAnalytics),
  ),
  { concurrent: true },
);

// TanStack creates its router before loaders or React run. One registry is shared
// by those loaders and React's RegistryContext; there is no module-global state.
export const createLoaderRegistry = () => Option.some(AtomRegistry.make());

// TanStack's sole browser Promise bridge executes an Effect using this registry.
// Route results are owned by Router, so there is no request atom or second cache.
const runForLoader = <A, E>({
  effect,
  context,
  signal,
}: Readonly<{
  effect: Effect.Effect<A, E, AtomRegistry.AtomRegistry>;
  context: LoaderContext;
  signal: AbortSignal;
}>) =>
  Effect.runPromise(
    context.registry.pipe(
      Effect.fromOption,
      Effect.mapError(() => new ApiConfigError({ reason: "unavailable" })),
      Effect.flatMap((registry) =>
        effect.pipe(Effect.provideService(AtomRegistry.AtomRegistry, registry)),
      ),
    ),
    { signal },
  );

export const loadPage = (
  request: Readonly<{ input: PageInput; context: LoaderContext; signal: AbortSignal }>,
) =>
  runForLoader({
    effect: browserApiClient.pipe(
      Effect.flatMap((client) => readPage({ client, input: request.input })),
      Effect.catchCause(rejectRouteLoad),
    ),
    context: request.context,
    signal: request.signal,
  });
export const loadCourses = (request: Readonly<{ context: LoaderContext; signal: AbortSignal }>) =>
  runForLoader({
    effect: browserApiClient.pipe(
      Effect.flatMap((client) => readCourses({ client })),
      Effect.catchCause(rejectRouteLoad),
    ),
    context: request.context,
    signal: request.signal,
  });
export const loadCourse = (
  request: Readonly<{ input: Schema.Json; context: LoaderContext; signal: AbortSignal }>,
) =>
  runForLoader({
    effect: browserApiClient.pipe(
      Effect.flatMap((client) => readCourseInput(client, request.input)),
      Effect.catchCause(rejectRouteLoad),
    ),
    context: request.context,
    signal: request.signal,
  });
export const loadTrainingPage = (
  request: Readonly<{ input: Schema.Json; context: LoaderContext; signal: AbortSignal }>,
) =>
  runForLoader({
    effect: browserApiClient.pipe(
      Effect.flatMap((client) => readTrainingPageInput(client, request.input)),
      Effect.catchCause(rejectRouteLoad),
    ),
    context: request.context,
    signal: request.signal,
  });

export const readWebsiteConfig = Effect.gen(function* () {
  const registry = yield* AtomRegistry.AtomRegistry;
  const config = yield* Schema.decodeEffect(WebsiteConfig)(registry.get(websiteConfigAtom));
  return yield* Schema.encodeEffect(WebsiteConfig)({
    ...config,
    appearance: registry.get(appearanceAtoms.state).choice,
  });
});

export const loadWebsiteConfig = (
  request: Readonly<{ context: LoaderContext; signal: AbortSignal }>,
) => runForLoader({ effect: readWebsiteConfig, context: request.context, signal: request.signal });
import * as Function from "effect/Function";
import * as Array from "effect/Array";
import { createMiddleware } from "@tanstack/react-start";
import type { NotFoundError } from "@tanstack/react-router";
import { getResponseStatus, setResponseStatus } from "@tanstack/react-start/server";
import * as NodeCrypto from "@effect/platform-node/NodeCrypto";
import type { PageInput } from "@common-practice/content/schemas";
import {
  applyResponsePolicy,
  responsePolicyHeaders,
} from "@common-practice/http/publishing-policy";
import type { ResponsePolicyRequest } from "@common-practice/http/publishing-policy";
import { IsolateIdentityLive } from "@common-practice/infrastructure/runtime/isolate-identity";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Logger from "effect/Logger";
import * as ManagedRuntime from "effect/ManagedRuntime";
import * as Option from "effect/Option";
import * as Record from "effect/Record";
import * as Result from "effect/Result";
import * as Schema from "effect/Schema";
import * as Cookies from "effect/http/Cookies";
import * as FetchHttpClient from "effect/http/FetchHttpClient";
import * as Headers from "effect/http/Headers";
import * as HttpServerRequest from "effect/http/HttpServerRequest";
import * as HttpServerResponse from "effect/http/HttpServerResponse";
import * as Url from "effect/http/Url";
import { ServerApiClient, ServerApiClientLive } from "./api/binding.adapter.layer";
import { WebsiteApiLive } from "./api/cloudflare.ingress";
import { WebsiteApi } from "./api/service";
import { WebsiteConfig } from "./api/page.egress";
import { forwardPageRepresentation } from "./api/representation.ingress";
import { observeWebsiteRequest } from "./api/website.telemetry";
import { HostAdapterError } from "./http/errors";
import { negotiatePage } from "./http/negotiation.ingress";
import { discoveryRepresentation } from "./http/discovery.ingress";
import { CaptureRelayLive } from "./analytics/relay/live.layer";
import { captureRelayRequest } from "./analytics/relay/request.ingress";
import { readCourses } from "./training/load.egress";
import { loadFailureStatus, rejectRouteLoad } from "./seo/load.failure";
import type { WebsiteLoadError } from "./seo/load.failure";
import * as Cause from "effect/Cause";
import { readPage, readCourseInput, readTrainingPageInput } from "./api/load.egress";
import * as Match from "effect/Match";
import { trainingRepresentation } from "./training/representation.ingress";
import {
  hasAppearanceCookie,
  readSavedAppearanceCookie,
  readAppearanceCookie,
} from "@common-practice/appearance/cookie-reader";
import { readAppearanceCookieHeader } from "@common-practice/appearance/input";
import { appearanceOptions } from "./appearance/settings";

// Request response adaptation stays at this one TanStack host boundary.
const rejectServerLoad = <E>(
  cause: Cause.Cause<E>,
): Effect.Effect<never, E | NotFoundError | WebsiteLoadError> => {
  if (Cause.hasInterruptsOnly(cause)) {
    return Effect.failCause(cause);
  }
  const status = loadFailureStatus(cause);
  return Effect.sync(() => {
    setResponseStatus(status);
  }).pipe(Effect.andThen(rejectRouteLoad(cause)));
};

const application = Layer.mergeAll(
  Logger.layer([Logger.consoleJson]),
  WebsiteApiLive,
  CaptureRelayLive.pipe(
    Layer.provide(
      FetchHttpClient.layer.pipe(
        Layer.provide(Layer.succeed(FetchHttpClient.RequestInit, { redirect: "manual" })),
      ),
    ),
  ),
  IsolateIdentityLive.pipe(Layer.provide(NodeCrypto.layer)),
);
type ApplicationServices = Layer.Success<typeof application>;

// TanStack owns this one frontend runtime. It supplies clients, never backend implementations.
const runtime = ManagedRuntime.make(application);
const runForRequest = <A, E>({
  effect,
  signal,
}: {
  readonly effect: Effect.Effect<A, E, ApplicationServices | ServerApiClient>;
  readonly signal?: AbortSignal;
}) => runtime.runPromise(effect.pipe(Effect.provide(ServerApiClientLive)), { signal });

export const handleCaptureRelayRequest = ({ request }: { readonly request: Request }) =>
  runForRequest({
    effect: captureRelayRequest.pipe(
      Effect.provideService(
        HttpServerRequest.HttpServerRequest,
        HttpServerRequest.fromWeb(request),
      ),
      Effect.map((response) =>
        HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD" }),
      ),
    ),
    signal: request.signal,
  });

export const handleMachineRequest = ({ request }: { readonly request: Request }) =>
  runForRequest({
    effect: WebsiteApi.pipe(
      Effect.flatMap((api) => api.forward(HttpServerRequest.fromWeb(request))),
      Effect.catchTag("ApiBindingError", () =>
        Effect.succeed(
          applyResponsePolicy({
            request: { adapter: "machine", method: request.method, pathname: Option.none() },
            response: HttpServerResponse.empty({ status: 503 }),
          }),
        ),
      ),
      Effect.map((response) =>
        HttpServerResponse.toWeb(response, { withoutBody: request.method === "HEAD" }),
      ),
    ),
    signal: request.signal,
  });

export const handlePageRepresentation = ({ request }: { readonly request: Request }) =>
  runForRequest({
    effect: Function.pipe(
      HttpServerRequest.fromWeb(request),
      forwardPageRepresentation,
      Effect.map((response) =>
        HttpServerResponse.toWeb(
          applyResponsePolicy({
            request: {
              adapter: "machine",
              method: request.method,
              pathname: Url.fromString(request.url).pipe(
                Result.getSuccess,
                Option.map((url) => url.pathname),
              ),
            },
            response,
          }),
          { withoutBody: request.method === "HEAD" },
        ),
      ),
    ),
    signal: request.signal,
  });

export const loadPage = ({
  input,
  signal,
}: {
  readonly input: PageInput;
  readonly signal: AbortSignal;
}) =>
  runForRequest({
    effect: ServerApiClient.pipe(
      Effect.flatMap(Effect.fromResult),
      Effect.flatMap((client) => readPage({ client, input })),
      Effect.catchCause(rejectServerLoad),
    ),
    signal,
  });

export const loadWebsiteConfig = ({
  request,
  signal,
}: {
  readonly request: Request;
  readonly signal: AbortSignal;
}) =>
  runForRequest({
    effect: Effect.gen(function* () {
      const header = yield* Effect.sync(() => request.headers.get("cookie") ?? "").pipe(
